442	\begin{lemma}[Common level of the Pauli question maps]\label{lem:pauli-question-cl-family}
443		\lean{MIPStarRE.QPBT.isTypedCondLinearFamily_pauliCL}
444		\uses{def:pauli-question-distribution, def:typed-cl-functions}
